import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import { Menu, X, Sun, Moon, Github, Cpu, Book, Layout, MessageSquare } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import './AcidFloatingNavbar.css';

export interface NavItem {
    id: string;
    name: string;
    link: string;
    icon?: React.ReactNode;
}

export interface AcidFloatingNavbarProps {
    items?: NavItem[];
    className?: string;
}

export const AcidFloatingNavbar = ({ items, className }: AcidFloatingNavbarProps) => {
    const [isOpen, setIsOpen] = useState(false);
    const [isDarkMode, setIsDarkMode] = useState(() => {
        return document.documentElement.getAttribute('data-theme') !== 'light';
    });
    const location = useLocation();

    useEffect(() => {
        document.documentElement.setAttribute('data-theme', isDarkMode ? 'dark' : 'light');
    }, [isDarkMode]);

    const defaultItems: NavItem[] = [
        { id: 'home', name: 'HOME', link: '/', icon: <Cpu size={16} /> },
        { id: 'docs', name: 'DOCS', link: '/docs', icon: <Book size={16} /> },
        { id: 'components', name: 'COMPONENTS', link: '/docs#button', icon: <Layout size={16} /> },
    ];

    const navItems = items || defaultItems;

    return (
        <nav className={clsx('ac-navbar-wrapper', className)}>
            <div className="ac-navbar-inner">
                <div className="ac-navbar-left">
                    <Link to="/" className="ac-nav-logo">
                        <MessageSquare className="text-brand" size={20} />
                        <span>ACID<span className="text-secondary">UI</span></span>
                    </Link>
                </div>

                <div className="ac-navbar-center ac-desktop-only">
                    {navItems.map((item) => (
                        <Link
                            key={item.id}
                            to={item.link}
                            className={clsx('ac-nav-item', location.pathname === item.link && 'active')}
                        >
                            {item.icon}
                            <span>{item.name}</span>
                        </Link>
                    ))}
                </div>

                <div className="ac-navbar-right">
                    <button
                        className="ac-icon-btn"
                        onClick={() => setIsDarkMode(!isDarkMode)}
                        aria-label="Toggle Theme"
                    >
                        {isDarkMode ? <Sun size={18} /> : <Moon size={18} />}
                    </button>

                    <a href="https://github.com" target="_blank" rel="noreferrer" className="ac-icon-btn ac-desktop-only">
                        <Github size={18} />
                    </a>

                    <button className="ac-menu-toggle ac-mobile-only" onClick={() => setIsOpen(!isOpen)}>
                        {isOpen ? <X size={20} /> : <Menu size={20} />}
                    </button>
                </div>
            </div>

            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        exit={{ opacity: 0, height: 0 }}
                        className="ac-mobile-dropdown"
                    >
                        <div className="ac-mobile-items">
                            {navItems.map((item) => (
                                <Link
                                    key={item.id}
                                    to={item.link}
                                    className="ac-mobile-item"
                                    onClick={() => setIsOpen(false)}
                                >
                                    {item.icon}
                                    <span>{item.name}</span>
                                </Link>
                            ))}
                            <a href="https://github.com" target="_blank" rel="noreferrer" className="ac-mobile-item">
                                <Github size={16} />
                                <span>GITHUB</span>
                            </a>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </nav>
    );
};

.ac-navbar-wrapper {
    position: fixed;
    top: 1.5rem;
    left: 50%;
    transform: translateX(-50%);
    width: calc(100% - 3rem);
    max-width: 1000px;
    z-index: 1000;
    background: rgba(var(--ac-bg-rgb, 0, 0, 0), 0.7);
    backdrop-filter: blur(12px) saturate(180%);
    border: 1px solid var(--ac-border-muted);
    border-radius: var(--ac-radius-lg);
    transition: all 0.3s ease;
}

[data-theme='light'] .ac-navbar-wrapper {
    background: rgba(255, 255, 255, 0.7);
    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.05);
}

.ac-navbar-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1.5rem;
    height: 60px;
}

.ac-nav-logo {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    text-decoration: none;
    font-family: var(--font-primary);
    font-weight: 700;
    font-size: 1.1rem;
    color: var(--ac-text-primary);
}

.ac-nav-logo .text-secondary {
    color: var(--ac-text-muted);
}

.ac-navbar-center {
    display: flex;
    gap: 0.5rem;
    background: var(--ac-surface);
    padding: 4px;
    border-radius: var(--ac-radius-md);
    border: 1px solid var(--ac-border-muted);
}

.ac-nav-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1.25rem;
    text-decoration: none;
    color: var(--ac-text-secondary);
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    border-radius: var(--ac-radius-sm);
    transition: all 0.2s ease;
}

.ac-nav-item:hover {
    color: var(--ac-text-primary);
    background: var(--ac-surface-hover);
}

.ac-nav-item.active {
    color: var(--ac-text-primary);
    background: var(--ac-bg);
    box-shadow: 0 0 0 1px var(--ac-border-bright);
}

.ac-navbar-right {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.ac-icon-btn {
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: transparent;
    border: 1px solid var(--ac-border-muted);
    border-radius: var(--ac-radius-sm);
    color: var(--ac-text-secondary);
    cursor: pointer;
    transition: all 0.2s ease;
}

.ac-icon-btn:hover {
    border-color: var(--ac-border-active);
    color: var(--ac-text-primary);
    background: var(--ac-surface-hover);
}

.ac-menu-toggle {
    display: none;
    background: transparent;
    border: none;
    color: var(--ac-text-primary);
    cursor: pointer;
}

/* Mobile Dropdown */
.ac-mobile-dropdown {
    border-top: 1px solid var(--ac-border-muted);
    overflow: hidden;
    background: var(--ac-surface);
    border-bottom-left-radius: var(--ac-radius-lg);
    border-bottom-right-radius: var(--ac-radius-lg);
}

.ac-mobile-items {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.ac-mobile-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1rem;
    text-decoration: none;
    color: var(--ac-text-secondary);
    font-family: var(--font-mono);
    font-size: 0.9rem;
    border-radius: var(--ac-radius-md);
}

.ac-mobile-item:active {
    background: var(--ac-surface-hover);
}

@media (max-width: 768px) {
    .ac-desktop-only {
        display: none;
    }

    .ac-menu-toggle {
        display: block;
    }
}
